//! Time zone data in the binary, the same on every OS. `bare` reads no zone file of the system.
//!
//! `tzdata.bin` and `windows.txt` are generated by `tools/gen_tz.py` from `data/tz/` (layout: see that script). The data
//! is read in place: a lookup is a binary search over the name table and a slice of the data. Nothing is built at start-up.

/// The tzdata release of the embedded data.
pub const VERSION: &str = "2026f";

static BIN: &[u8] = include_bytes!("tzdata.bin");
static WINDOWS: &str = include_str!("windows.txt");

fn u16_at(i: usize) -> usize {
    u16::from_le_bytes([BIN[i], BIN[i + 1]]) as usize
}

fn u32_at(i: usize) -> usize {
    u32::from_le_bytes([BIN[i], BIN[i + 1], BIN[i + 2], BIN[i + 3]]) as usize
}

/// Number of zone names.
pub fn len() -> usize {
    u32_at(0)
}

/// The name and the slim TZif file of entry `i` (`i < len()`). Names are in ascending order.
pub fn entry(i: usize) -> (&'static str, &'static [u8]) {
    let (count, names_len) = (u32_at(0), u32_at(4));
    let names = 8 + 8 * count;
    let data = names + names_len;
    let e = 8 + 8 * i;
    let start = u16_at(e);
    let end = if i + 1 < count { u16_at(e + 8) } else { names_len };
    let name = std::str::from_utf8(&BIN[names + start..names + end]).expect("generated names are ASCII");
    let off = data + u32_at(e + 2);
    (name, &BIN[off..off + u16_at(e + 6)])
}

/// The slim TZif file of zone `name`. The name must have the case of the IANA name (`Asia/Kolkata`).
pub fn find(name: &str) -> Option<&'static [u8]> {
    let (mut lo, mut hi) = (0, len());
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (n, bytes) = entry(mid);
        match n.cmp(name) {
            std::cmp::Ordering::Equal => return Some(bytes),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

/// The IANA name for the key of a Windows time zone (`Pacific Standard Time`): the CLDR row for territory 001.
pub fn windows_zone(key: &str) -> Option<&'static str> {
    WINDOWS.lines().find_map(|l| l.split_once('\t').filter(|(k, _)| *k == key).map(|(_, v)| v))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_are_sorted_and_found() {
        assert_eq!(len(), 597);
        let mut prev = "";
        for i in 0..len() {
            let (n, bytes) = entry(i);
            assert!(n > prev, "{prev} {n}");
            assert!(bytes.starts_with(b"TZif"), "{n}");
            assert_eq!(find(n), Some(bytes), "{n}");
            prev = n;
        }
    }

    #[test]
    fn links_share_the_data_and_bad_names_miss() {
        assert_eq!(find("Asia/Kolkata"), find("Asia/Calcutta"));
        assert_ne!(find("Asia/Kolkata"), find("America/New_York"));
        for bad in ["", "asia/kolkata", "No/Such", "Asia", "Asia/", "Factory", "posixrules", "right/UTC", "Asia/Kolkata\0"] {
            assert_eq!(find(bad), None, "{bad:?}");
        }
    }

    #[test]
    fn windows_ids_map_to_names_with_data() {
        assert_eq!(windows_zone("Pacific Standard Time"), Some("America/Los_Angeles"));
        assert_eq!(windows_zone("India Standard Time"), Some("Asia/Calcutta"));
        assert_eq!(windows_zone("No Such Time"), None);
        assert_eq!(WINDOWS.lines().count(), 142);
        for l in WINDOWS.lines() {
            let (k, v) = l.split_once('\t').unwrap();
            assert!(find(v).is_some(), "{k}: {v}");
        }
    }
}
